SELECT    DISTINCT `spree_products`.*  FROM    `spree_products`    INNER JOIN `spree_products_taxons` ON `spree_products_taxons`.`product_id` = `spree_products`.`id`    INNER JOIN `spree_taxons` ON `spree_taxons`.`id` = `spree_products_taxons`.`taxon_id`    INNER JOIN `spree_variants` ON `spree_variants`.`deleted_at` IS NULL    AND `spree_variants`.`is_master` = ?    AND `spree_variants`.`product_id` = `spree_products`.`id`    INNER JOIN `spree_prices` ON `spree_prices`.`deleted_at` IS NULL    AND `spree_prices`.`variant_id` = `spree_variants`.`id`  WHERE    `spree_products`.`deleted_at` IS NULL    AND `spree_taxons`.`id` IN (?, ?)    AND (     `spree_products`.deleted_at IS NULL      or `spree_products`.deleted_at >= '2020-05-24 13:55:57.476059'   )    AND (     `spree_products`.discontinue_on IS NULL      or `spree_products`.discontinue_on >= '2020-05-24 13:55:57.476251'   )    AND (     `spree_products`.available_on <= '2020-05-24 13:55:57.476241'   )
SELECT    DISTINCT `spree_products`.*  FROM    `spree_products`    INNER JOIN `spree_products_taxons` ON `spree_products_taxons`.`product_id` = `spree_products`.`id`    INNER JOIN `spree_variants` ON `spree_variants`.`deleted_at` IS NULL    AND `spree_variants`.`is_master` = true   AND `spree_variants`.`product_id` = `spree_products`.`id`    INNER JOIN `spree_prices` ON `spree_prices`.`deleted_at` IS NULL    AND `spree_prices`.`variant_id` = `spree_variants`.`id`  WHERE    `spree_products`.`deleted_at` IS NULL    AND `spree_products_taxons`.`taxon_id` IN (1)    AND (     `spree_products`.deleted_at IS NULL      or `spree_products`.deleted_at >= '2020-05-24 13:49:27.370098'   )    AND (     `spree_products`.discontinue_on IS NULL      or `spree_products`.discontinue_on >= '2020-05-24 13:49:27.370323'   )    AND (     `spree_products`.available_on <= '2020-05-24 13:49:27.370311'   )
select p.id from spree_products p inner join spree_products_taxons op on p.id = op.product_id
